    assign dc_mem_resp_valid = dmem_valid & dmem_ready;
    assign dc_mem_resp_data  = dmem_rdata;

    // ---------------------------------------------------------------
    // Branch predictor
    // ---------------------------------------------------------------
    branch_predictor u_branch_predictor (
        .clk              (clk),
        .rst_n            (rst_n),
        .bp_lookup_pc     (bp_lookup_pc),
