        end
    end

    always_comb begin
        dbg_reg_data = 32'b0;
        if (dbg_reg_addr != 5'd0)
            dbg_reg_data = regs[dbg_reg_addr];
    end

    assign reg_x10 = regs[10];

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            for (int i = 1; i < 32; i++)
                regs[i] <= 32'b0;
        end else if (wb_reg_write && (wb_rd != 5'd0)) begin
            regs[wb_rd] <= wb_data;
        end
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            id2ex_valid     <= 1'b0;
            id2ex_pc        <= 32'b0;
            id2ex_pc4       <= 32'b0;
            id2ex_insn      <= 32'b0;
            id2ex_rs1_val   <= 32'b0;
            id2ex_rs2_val   <= 32'b0;
            id2ex_imm       <= 32'b0;
            id2ex_rs1       <= 5'b0;
            id2ex_rs2       <= 5'b0;
            id2ex_rd        <= 5'b0;
            id2ex_alu_op    <= ALU_ADD;
            id2ex_op_a_pc   <= 1'b0;
            id2ex_op_b_imm  <= 1'b0;
            id2ex_reg_write <= 1'b0;
            id2ex_mem_read  <= 1'b0;
            id2ex_mem_write <= 1'b0;
            id2ex_branch    <= 1'b0;
            id2ex_jump      <= 1'b0;
            id2ex_wb_sel    <= WB_ALU;
            id2ex_funct3    <= 3'b0;
            id2ex_is_ecall  <= 1'b0;
            idex_pred_valid    <= 1'b0;
            idex_pred_next_pc  <= 32'b0;
        end else if (mem_stall) begin
            id2ex_valid     <= id2ex_valid;
        end else if (flush_id_ex) begin
            id2ex_valid     <= 1'b0;
            id2ex_pc        <= 32'b0;
            id2ex_pc4       <= 32'b0;
            id2ex_insn      <= 32'b0;
            id2ex_rs1_val   <= 32'b0;
            id2ex_rs2_val   <= 32'b0;
            id2ex_imm       <= 32'b0;
            id2ex_rs1       <= 5'b0;
            id2ex_rs2       <= 5'b0;
            id2ex_rd        <= 5'b0;
            id2ex_alu_op    <= ALU_ADD;
            id2ex_op_a_pc   <= 1'b0;
            id2ex_op_b_imm  <= 1'b0;
            id2ex_reg_write <= 1'b0;
            id2ex_mem_read  <= 1'b0;
            id2ex_mem_write <= 1'b0;
            id2ex_branch    <= 1'b0;
            id2ex_jump      <= 1'b0;
            id2ex_wb_sel    <= WB_ALU;
            id2ex_funct3    <= 3'b0;
            id2ex_is_ecall  <= 1'b0;
            idex_pred_valid    <= 1'b0;
            idex_pred_next_pc  <= 32'b0;
        end else begin
