            id2ex_insn      <= if2id_insn;
            id2ex_rs1_val   <= rs1_val;
            id2ex_rs2_val   <= rs2_val;
            id2ex_imm       <= imm;
            id2ex_rs1       <= rs1;
            id2ex_rs2       <= rs2;
            id2ex_rd        <= rd;
            id2ex_alu_op    <= alu_op;
            id2ex_op_a_pc   <= op_a_pc;
            id2ex_op_b_imm  <= op_b_imm;
            id2ex_reg_write <= reg_write;
            id2ex_mem_read  <= mem_read;
            id2ex_mem_write <= mem_write;
            id2ex_branch    <= branch;
            id2ex_jump      <= jump;
            id2ex_wb_sel    <= wb_sel;
            id2ex_funct3    <= funct3;
