                if2id_pc    <= pc;
                if2id_pc4   <= pc + 32'd4;
                if2id_insn  <= cpu_resp_data;
                ifid_pred_valid     <= inflight_pred_valid;
                ifid_pred_next_pc   <= inflight_pred_next_pc;
