                // 流水线暂停时 IF/ID 必须保持，不能在 stall 分支丢弃
                // 已经取到的指令，否则 load-use/mem_stall 后的指令会消失。
                if2id_valid <= if2id_valid;
            end else begin
                if (req_pending && cpu_req_ready) begin
                    req_pending <= 1'b0;
                    if2id_valid <= 1'b0;
                    inflight_pred_valid   <= bp_pred_valid;
                    inflight_pred_next_pc <= next_pc;
                end else begin
                    if2id_valid <= 1'b0;
                end
            end
        end
    end

endmodule
"}, {"path": "rtl/icache.sv", "content": "module icache (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        halted,
    input  logic        flush,
    input  logic [1:0]  flush_epoch,
    input  logic        cpu_req_valid,
    input  logic [31:0] cpu_req_addr,
    output logic        cpu_req_ready,
    output logic        cpu_resp_valid,
    output logic [31:0] cpu_resp_data,
    output logic        mem_req_valid,
    output logic [31:0] mem_req_addr,
    input  logic        mem_req_ready,
    input  logic        mem_resp_valid,
    input  logic [31:0] mem_resp_data
);

    localparam logic [1:0] S_IDLE   = 2'd0;
    localparam logic [1:0] S_REFILL = 2'd1;

    logic [31:0]  tag_arr   [0:15];
    logic [127:0] data_arr  [0:15];
    logic         valid_arr [0:15];

    logic [1:0]   state;
    logic [1:0]   refill_cnt;
    logic [31:0]  refill_base;
    logic [31:0]  refill_tag;
    logic [3:0]   refill_idx;
    logic [1:0]   refill_epoch;
    logic [127:0] refill_data;
    logic [1:0]   refill_word;

    logic         resp_valid_r;
    logic [31:0]  resp_data_r;

    logic [3:0]   req_idx;
    logic [31:0]  req_tag;
    logic [1:0]   req_word;
    logic         hit;
    logic [31:0]  hit_data;

    assign req_idx  = cpu_req_addr[7:4];
    assign req_tag  = cpu_req_addr[31:8];
    assign req_word = cpu_req_addr[3:2];

    assign hit = valid_arr[req_idx] && (tag_arr[req_idx] == req_tag);

    always_comb begin
        hit_data = 32'b0;
        case (req_word)
            2'd0: hit_data = data_arr[req_idx][31:0];
            2'd1: hit_data = data_arr[req_idx][63:32];
            2'd2: hit_data = data_arr[req_idx][95:64];
            2'd3: hit_data = data_arr[req_idx][127:96];
            default: hit_data = 32'b0;
        endcase
    end

    assign cpu_req_ready = rst_n && !halted && (state == S_IDLE) && !resp_valid_r;

    assign mem_req_valid = rst_n && !halted && (state == S_REFILL);
    assign mem_req_addr  = refill_base + {refill_cnt, 2'b00};

    assign cpu_resp_valid = resp_valid_r;
    assign cpu_resp_data  = resp_data_r;

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            state        <= S_IDLE;
            refill_cnt   <= 2'd0;
            refill_base  <= 32'b0;
            refill_tag   <= 32'b0;
            refill_idx   <= 4'b0;
            refill_epoch <= 2'b0;
            refill_data  <= 128'b0;
            refill_word  <= 2'b0;
            resp_valid_r <= 1'b0;
            resp_data_r  <= 32'b0;
            for (int i = 0; i < 16; i = i + 1) begin
                valid_arr[i] <= 1'b0;
                tag_arr[i]   <= 32'b0;
                data_arr[i]  <= 128'b0;
            end
        end else if (halted) begin
            resp_valid_r <= 1'b0;
        end else begin
            resp_valid_r <= 1'b0;

            // flush 不能打断已经发出的外部 refill 请求，否则 imem_addr/
            // imem_valid 会在 imem_ready 前变化。让 refill 完成，仅通过
            // refill_epoch 丢弃过期数据。
            case (state)
                S_IDLE: begin
                    if (cpu_req_valid && cpu_req_ready) begin
                        if (hit) begin
                            resp_valid_r <= 1'b1;
                            resp_data_r  <= hit_data;
                        end else begin
                            state        <= S_REFILL;
                            refill_cnt   <= 2'd0;
                            refill_base  <= {cpu_req_addr[31:4], 4'b0000};
                            refill_tag   <= req_tag;
                            refill_idx   <= req_idx;
                            refill_epoch <= flush_epoch;
                            refill_data  <= 128'b0;
                            refill_word  <= req_word;
                        end
                    end
                end
                S_REFILL: begin
                    if (mem_req_valid && mem_req_ready) begin
                        case (refill_cnt)
                            2'd0: refill_data[31:0]   <= mem_resp_data;
                            2'd1: refill_data[63:32]  <= mem_resp_data;
                            2'd2: refill_data[95:64]  <= mem_resp_data;
                            2'd3: refill_data[127:96] <= mem_resp_data;
                            default: ;
                        endcase
                        if (refill_cnt == 2'd3) begin
                            // 即使期间发生 redirect，也把有效行安装进 I-Cache；
                            // 仅抑制过期 refill 的响应。否则每次分支都会丢掉
                            // 正在填充的行，循环永远无法 reuse。
                            valid_arr[refill_idx] <= 1'b1;
                            tag_arr[refill_idx]   <= refill_tag;
                            data_arr[refill_idx]  <= refill_data |
                                ({96'b0, mem_resp_data} << {refill_cnt, 5'b00000});
                            if (flush_epoch == refill_epoch) begin
                                resp_valid_r <= 1'b1;
                                case (refill_word)
                                    2'd0: resp_data_r <= refill_data[31:0];
                                    2'd1: resp_data_r <= refill_data[63:32];
                                    2'd2: resp_data_r <= refill_data[95:64];
                                    default: resp_data_r <= mem_resp_data;
                                endcase
                            end
                            state <= S_IDLE;
                        end else begin
                            refill_cnt <= refill_cnt + 2'd1;
                        end
                    end
                end
                default: state <= S_IDLE;
            endcase
        end
    end

endmodule
"}], "notes": "Root cause: EX only redirected on taken branches/jumps, so a predicted-taken branch resolving not-taken never flushed the predicted path, causing runaway loops and missing resolve events. Fix in ex_stage: redirect on every valid control transfer (branch taken->target, branch not-taken->pc4, JAL/JALR->jump target). Fix in rv32i5: bp_resolve_valid now fires for every valid branch/jump (not just redirects), bp_resolve_taken reflects actual branch outcome, and bp_mispredict compares the actual next PC against the in-flight prediction (idex_pred_next_pc) rather than blindly asserting on every redirect. Verified timing corners: redirect still has priority over ECALL/stall in IF; IF/ID valid held during stall; one-cycle cpu_resp_valid captured unconditionally; ECALL propagation and WB-only halt commit untouched; I-cache refill installs line and gates only response by epoch; ready/valid held until ready. if_stage/icache unchanged (already correct)." }
